import React,{useEffect,useMemo,useState} from 'react';
import {Link,useNavigate,useParams,useLocation} from 'react-router-dom';
import {AreaChart,Area,ResponsiveContainer,CartesianGrid,XAxis,YAxis,Tooltip,BarChart,Bar,PieChart,Pie,Cell} from 'recharts';
import {Activity,ArrowLeft,ArrowRight,ArrowUpLeft,CalendarCheck2,CalendarDays,CalendarPlus,CheckCircle2,ChevronLeft,ChevronRight,Clock3,Download,Eye,FileHeart,FileText,FlaskConical,HeartPulse,Inbox,LockKeyhole,MessageSquare,NotebookPen,Pill,Plus,Printer,ReceiptText,RefreshCw,Save,Search,Send,ShieldCheck,Stethoscope,Upload,UserRound,Users,Wallet,Mic,Sun,Moon,Settings,Building2,Globe,Palette,Bell,Clock4,Database,KeyRound,LifeBuoy,MoreHorizontal,Trash2,Edit3,Paperclip,X,AlertTriangle,Copy,Check,Star,FilePlus2,Phone,MapPin} from 'lucide-react';
import {api,downloadFile,fileStorageEnabled} from '../services/api.js';
import {useAuth} from '../app/AuthContext.jsx';
import {Button,Card,PageHeading,StatCard,StatusBadge,Badge,EmptyState,Field,Input,Select,Textarea,Toggle,Modal,useToast} from '../components/UI.jsx';
import ResourcePage,{PatientFilePage} from './ResourcePage.jsx';

const money=n=>`${Number(n||0).toLocaleString('en-US',{maximumFractionDigits:0})} ج.م`;
const fmtDate=(value,time=false)=>{if(!value)return'—';const d=new Date(value);return Number.isNaN(+d)?'—':new Intl.DateTimeFormat('ar-EG-u-nu-latn',{weekday:time?'short':undefined,day:'numeric',month:'short',year:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(d)};
const homeFor=role=>role==='patient'?'/portal':role==='doctor'?'/doctor':role==='receptionist'?'/reception':'/admin';

export function PortalHome(){const {user}=useAuth();const [patient,setPatient]=useState(null);const [appointment,setAppointment]=useState(null);const [queue,setQueue]=useState(null);const [notifications,setNotifications]=useState([]);const [prescriptions,setPrescriptions]=useState([]);const [labs,setLabs]=useState([]);const [loading,setLoading]=useState(true);const navigate=useNavigate();const toast=useToast();
 useEffect(()=>{let live=true;Promise.all([api('/patients?pageSize=1').catch(()=>({data:[]})),api('/appointments?pageSize=10').catch(()=>({data:[]})),api('/queue/me').catch(()=>({data:null})),api('/notifications').catch(()=>({data:[]})),api('/prescriptions').catch(()=>({data:[]})),api('/lab-orders').catch(()=>({data:[]}))]).then(([p,a,q,n,r,l])=>{if(!live)return;setPatient(p.data?.[0]||null);setAppointment((a.data||[]).filter(x=>!['cancelled','completed'].includes(x.status)).sort((x,y)=>new Date(x.startAt)-new Date(y.startAt))[0]||null);setQueue(q.data||null);setNotifications((n.data||[]).slice(0,3));setPrescriptions(r.data||[]);setLabs(l.data||[]);}).finally(()=>live&&setLoading(false));return()=>{live=false;};},[]);
 const fullName=patient?.fullName||user?.fullName||'المريض';const next=appointment;
 return <div className="portal-home"><PageHeading eyebrow="بوابة المريض" title={`مرحبًا، ${fullName.split(' ')[0]}`} description="ملفك الطبي وخدمات العيادة في مكان واحد." actions={<Link className="btn btn-primary" to="/portal/book"><CalendarPlus size={16}/> احجز كشفًا</Link>}/>
  <div className="portal-hero-grid"><Card className="portal-next-card"><div className="portal-next-icon"><CalendarCheck2 size={22}/></div><div className="portal-next-content"><small>موعدك القادم</small>{loading?<div className="skeleton-line"/>:next?<><h2>{fmtDate(next.startAt,true)}</h2><p><Stethoscope size={15}/> {next.doctorName} · {next.serviceName||'زيارة طبية'}</p><div className="portal-next-meta"><StatusBadge status={next.status}/><span>ملف رقم {patient?.fileNo||'—'}</span></div></>:<><h2>لا يوجد موعد قادم</h2><p>احجز موعدًا مناسبًا مع طبيبك.</p></>}<Link className="text-link" to="/portal/appointments">عرض مواعيدي <ArrowLeft size={15}/></Link></div><div className="portal-next-art"><div className="portal-art-orbit"/><CalendarDays size={92}/></div></Card>
   <Card className="portal-queue-card"><div className="card-heading"><div><h2>دورك في العيادة</h2><p>حالة الطابور اليوم</p></div><Clock3 size={19} className="muted-icon"/></div>{queue?.data?<><div className="portal-turn"><small>رقمك</small><strong>{queue.data.number}</strong><Badge tone={queue.data.status==='called'?'success':'warning'}>{queue.data.status==='called'?'حان دورك':'في الانتظار'}</Badge></div><div className="queue-progress"><i style={{width:`${Math.max(10,Math.min(95,100-(queue.patientsAhead||0)*12))}%`}}/></div><p className="wait-text">{queue.patientsAhead?`قبلك ${queue.patientsAhead} مرضى · انتظار متوقع ${queue.estimatedWaitMinutes} دقيقة`:'أنت التالي في الطابور'}</p><Link className="text-link" to="/portal/queue">تفاصيل الطابور <ArrowLeft size={15}/></Link></>:<div className="queue-empty"><span>لا يوجد دور نشط لك الآن.</span><Link to="/portal/appointments">عرض المواعيد</Link></div>}</Card></div>
  <div className="portal-stat-grid"><StatCard label="المواعيد القادمة" value={next?1:0} icon={CalendarCheck2} caption="مواعيد مؤكدة" tone="teal"/><StatCard label="الروشتات" value={prescriptions.length} icon={FileText} caption="يمكن عرضها وتنزيلها" tone="aqua"/><StatCard label="التحاليل" value={labs.length} icon={FlaskConical} caption="نتائج وطلبات مرتبطة بملفك" tone="gold"/><StatCard label="رسائل جديدة" value={notifications.filter(x=>!x.read_at).length} icon={Bell} caption="إشعارات العيادة" tone="violet"/></div>
  <div className="portal-content-grid"><Card><div className="card-heading"><div><h2>ملخص ملفك الطبي</h2><p>المعلومات التي يراجعها فريقك الطبي</p></div><Link to="/portal/medical-file" className="text-link">عرض الملف <ArrowLeft size={15}/></Link></div><div className="portal-medical-summary"><div><span><HeartPulse size={17}/></span><small>الحساسية</small><b>{patient?.medical?.allergies||'لا توجد حساسية مسجلة'}</b></div><div><span><Activity size={17}/></span><small>الأمراض المزمنة</small><b>{patient?.medical?.chronicConditions||'لا توجد حالات مسجلة'}</b></div><div><span><Pill size={17}/></span><small>الأدوية الحالية</small><b>{patient?.medical?.currentMedications||'لا توجد أدوية مسجلة'}</b></div></div></Card><Card className="portal-notifs-card"><div className="card-heading"><div><h2>آخر الإشعارات</h2><p>تحديثات من العيادة</p></div><Link to="/portal/notifications" className="text-link">عرض الكل</Link></div>{notifications.length?<div className="portal-notif-list">{notifications.map(n=><div key={n.id} className="portal-notif"><span className="notif-circle"><Bell size={15}/></span><div><b>{n.title}</b><p>{n.body}</p><small>{fmtDate(n.created_at,true)}</small></div></div>)}</div>:<EmptyState icon={Bell} title="لا توجد إشعارات" description="ستظهر التحديثات المهمة هنا."/>}</Card></div>
  <div className="portal-quick-links"><Link to="/portal/appointments"><CalendarDays size={18}/> مواعيدي <ArrowLeft size={14}/></Link><Link to="/portal/prescriptions"><FileText size={18}/> الروشتات <ArrowLeft size={14}/></Link><Link to="/portal/labs"><FlaskConical size={18}/> التحاليل والملفات <ArrowLeft size={14}/></Link><Link to="/portal/support"><MessageSquare size={18}/> خدمة العملاء <ArrowLeft size={14}/></Link></div>
 </div>;
}

export function PatientQueuePage(){const [q,setQ]=useState(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const load=()=>{setLoading(true);api('/queue/me').then(r=>{setQ(r);setError('')}).catch(e=>setError(e.message)).finally(()=>setLoading(false));};useEffect(()=>{load();const t=setInterval(load,12000);return()=>clearInterval(t);},[]);return <div className="portal-queue-page"><PageHeading eyebrow="بوابة المريض" title="الطابور" description="تابع رقمك ووقت الانتظار المتوقع مباشرة." actions={<Button variant="outline" icon={RefreshCw} onClick={load}>تحديث الحالة</Button>}/>{error&&<div className="form-alert error">{error}</div>}<Card className="patient-turn-card"><div className="turn-card-top"><div><span className="eyebrow">الدور الحالي</span><h2>رقمك في الطابور</h2></div><Badge tone={q?.data?.status==='called'?'success':'warning'}>{q?.data?.status==='called'?'حان دورك':q?.data?'في الانتظار':'لا يوجد دور نشط'}</Badge></div>{loading?<div className="skeleton-line"/>:q?.data?<><div className="big-turn-number">{q.data.number}</div><div className="progress-track"><span style={{width:`${Math.max(10,Math.min(92,100-(q.patientsAhead||0)*12))}%`}}/></div><div className="turn-estimate"><div><b>{q.patientsAhead??0}</b><small>مرضى قبلك</small></div><div><b>{q.estimatedWaitMinutes??0} د</b><small>الانتظار المتوقع</small></div><div><b>{q.data.doctorName||'الطبيب'}</b><small>الطبيب</small></div></div><p className="turn-notice"><Bell size={16}/> سننبهك عندما يقترب دورك. يرجى البقاء بالقرب من العيادة.</p></>:<EmptyState icon={Clock3} title="لا يوجد دور نشط" description="تظهر معلومات الطابور بعد تسجيل وصولك لموعدك." action={<Link className="btn btn-primary" to="/portal/appointments">عرض المواعيد</Link>}/>}</Card></div>}

export function BookingPage(){const toast=useToast();const navigate=useNavigate();const [doctors,setDoctors]=useState([]);const [services,setServices]=useState([]);const [patient,setPatient]=useState(null);const [doctorId,setDoctorId]=useState('');const [serviceId,setServiceId]=useState('');const [date,setDate]=useState('');const [slots,setSlots]=useState([]);const [slot,setSlot]=useState('');const [loading,setLoading]=useState(true);const [slotLoading,setSlotLoading]=useState(false);const [saving,setSaving]=useState(false);const [reason,setReason]=useState('');
 useEffect(()=>{const d=new Date(Date.now()+48*3600000);setDate(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);Promise.all([api('/doctors'),api('/services'),api('/patients?pageSize=1')]).then(([docs,s,p])=>{setDoctors(docs.data||[]);setServices(s.data||[]);setPatient(p.data?.[0]||null);setDoctorId(String(docs.data?.[0]?.id||''));setServiceId(String(s.data?.[0]?.id||''));}).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));},[]);
 useEffect(()=>{if(!doctorId||!date)return;setSlotLoading(true);api(`/doctors/${doctorId}/availability?date=${date}`).then(r=>{setSlots(r.data||[]);setSlot('');}).catch(()=>setSlots([])).finally(()=>setSlotLoading(false));},[doctorId,date]);
 const chosenService=services.find(s=>String(s.id)===serviceId);const book=async()=>{if(!patient||!doctorId||!slot){toast('اختر الطبيب والتاريخ والوقت المتاح.','error');return;}setSaving(true);try{const start=new Date(slot);const end=new Date(start.getTime()+Number(chosenService?.durationMinutes||30)*60000);const r=await api('/appointments',{method:'POST',body:JSON.stringify({patientId:patient.id,doctorId:Number(doctorId),serviceId:serviceId?Number(serviceId):null,type:'first',startAt:start.toISOString(),endAt:end.toISOString(),reason})});toast(r.data?.status==='pending'?'تم إرسال طلب الحجز للمراجعة.':'تم تأكيد موعدك.');navigate('/portal/appointments');}catch(e){toast(e.message,'error');}finally{setSaving(false);}};
 return <div className="booking-page"><PageHeading eyebrow="المواعيد" title="حجز كشف جديد" description="اختر الطبيب والخدمة والوقت المناسب من المواعيد المتاحة."/><div className="booking-layout"><Card className="booking-form-card"><div className="booking-step"><span>1</span><div><b>اختر الطبيب والخدمة</b><small>حدد من ترغب بزيارته</small></div></div><div className="form-grid two"><Field label="الطبيب" required><Select value={doctorId} onChange={e=>setDoctorId(e.target.value)} disabled={loading}><option value="">اختر الطبيب</option>{doctors.map(d=><option value={d.id} key={d.id}>{d.fullName} · {d.specialty}</option>)}</Select></Field><Field label="نوع الزيارة"><Select value={serviceId} onChange={e=>setServiceId(e.target.value)}><option value="">اختر الخدمة</option>{services.map(s=><option value={s.id} key={s.id}>{s.name} · {money(s.price)}</option>)}</Select></Field></div>{chosenService&&<div className="booking-service-note"><Clock3 size={16}/> مدة الزيارة {chosenService.durationMinutes} دقيقة <span>·</span> {money(chosenService.price)}</div>}<hr className="soft-separator"/><div className="booking-step"><span>2</span><div><b>اختر التاريخ</b><small>المواعيد المتاحة تتحدث تلقائيًا</small></div></div><Field label="تاريخ الزيارة" required><Input type="date" value={date} min={new Date().toISOString().slice(0,10)} onChange={e=>setDate(e.target.value)} required/></Field><div className="slots-heading"><b>المواعيد المتاحة</b>{slotLoading&&<span className="muted">جارٍ البحث...</span>}</div>{slotLoading?<div className="slot-skeleton"><i/><i/><i/><i/></div>:slots.length?<div className="time-slot-grid">{slots.map(s=><button key={s.startAt} className={slot===s.startAt?'selected':''} onClick={()=>setSlot(s.startAt)}>{formatSlot(s.startAt)}</button>)}</div>:<div className="slots-empty"><CalendarDays size={19}/><span>لا توجد أوقات متاحة في هذا اليوم. جرّب تاريخًا آخر.</span></div>}<Field label="سبب الزيارة"><Textarea rows={3} value={reason} onChange={e=>setReason(e.target.value)} placeholder="اكتب ملاحظة للطبيب إن وجدت"/></Field><div className="booking-actions"><Button variant="ghost" onClick={()=>navigate('/portal')}>إلغاء</Button><Button onClick={book} loading={saving} disabled={!slot}>تأكيد الحجز <ArrowLeft size={16}/></Button></div></Card><Card className="booking-aside"><div className="booking-aside-icon"><CalendarCheck2 size={25}/></div><h2>مواعيد تناسب يومك</h2><p>يعرض النظام الأوقات المتاحة فقط، ويتحقق من عدم تعارضها مع جدول الطبيب.</p><div className="booking-reassurance"><span><CheckCircle2 size={17}/> تأكيد فوري أو بعد مراجعة الاستقبال</span><span><ShieldCheck size={17}/> معلوماتك لا تظهر إلا للفريق المصرح له</span><span><Bell size={17}/> تذكير قبل الموعد</span></div><div className="booking-summary"><b>ملخص الحجز</b><span><small>المريض</small>{patient?.fullName||'—'}</span><span><small>الخدمة</small>{chosenService?.name||'—'}</span><span><small>التاريخ والوقت</small>{slot?`${fmtDate(slot,true)}`:'لم يتم الاختيار'}</span><span className="booking-price"><small>السعر</small><strong>{money(chosenService?.price)}</strong></span></div></Card></div></div>}
function formatSlot(value){return new Intl.DateTimeFormat('ar-EG-u-nu-latn',{hour:'2-digit',minute:'2-digit'}).format(new Date(value));}

export function PortalMedicalPage(){const [id,setId]=useState(null);const [loading,setLoading]=useState(true);const toast=useToast();useEffect(()=>{api('/patients?pageSize=1').then(r=>setId(r.data?.[0]?.id||null)).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));},[]);if(loading)return <div className="profile-skeleton"><i/><i/></div>;if(!id)return <EmptyState icon={FileHeart} title="ملفك الطبي غير جاهز" description="تواصل مع العيادة لإكمال تسجيل ملفك."/>;return <PatientFilePage patientId={id}/>}

export function NotificationsPage(){const [rows,setRows]=useState([]);const [loading,setLoading]=useState(true);const toast=useToast();const load=()=>{setLoading(true);api('/notifications').then(r=>setRows(r.data||[])).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));};useEffect(()=>{load();},[]);const mark=async(id)=>{try{await api(`/notifications/${id}/read`,{method:'POST'});setRows(r=>r.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x));}catch(e){toast(e.message,'error');}};const allRead=async()=>{try{await api('/notifications/read-all',{method:'POST'});setRows(r=>r.map(x=>({...x,read_at:new Date().toISOString()})));toast('تم تحديد الإشعارات كمقروءة.');}catch(e){toast(e.message,'error');}};return <div className="notifications-page"><PageHeading eyebrow="بوابة المريض" title="الإشعارات" description="التنبيهات والتحديثات الخاصة بملفك ومواعيدك." actions={<Button variant="outline" icon={Check} onClick={allRead}>تحديد الكل كمقروء</Button>}/><Card className="notifications-card">{loading?<div className="skeleton-table"><i/><i/><i/></div>:rows.length?<div className="notifications-list">{rows.map(n=><div key={n.id} className={`notification-row ${n.read_at?'read':''}`}><span className={`notification-icon ${n.type}`}><Bell size={17}/></span><div className="notification-copy"><div><b>{n.title}</b><small>{fmtDate(n.created_at,true)}</small></div><p>{n.body}</p>{n.link&&<Link to={n.link} className="text-link">فتح التفاصيل <ArrowLeft size={14}/></Link>}</div>{!n.read_at&&<button className="mark-read" onClick={()=>mark(n.id)}>تحديد كمقروء</button>}</div>)}</div>:<EmptyState icon={Bell} title="لا توجد إشعارات" description="ستظهر هنا التحديثات والتنبيهات الجديدة."/>}</Card></div>}

export function SettingsPage(){const {user,changePassword,refresh}=useAuth();const toast=useToast();const [tab,setTab]=useState(user.role==='admin'?'general':'profile');const [settings,setSettings]=useState({});const [saving,setSaving]=useState(false);const [password,setPassword]=useState({current:'',next:'',confirm:''});const [profile,setProfile]=useState({fullName:user.fullName||'',email:user.email||'',phone:user.phone||'',language:user.language||'ar',theme:user.theme||'light'});const [hours,setHours]=useState([]);const [permissions,setPermissions]=useState({});const [backups,setBackups]=useState([]);const [secretOpen,setSecretOpen]=useState(false);const isAdmin=user.role==='admin';
 const tabs=isAdmin?[['general','عام',Building2],['booking','الحجز والمواعيد',CalendarDays],['billing','الفواتير والمدفوعات',ReceiptText],['notifications','الإشعارات',Bell],['security','الأمان والصلاحيات',ShieldCheck],['backup','النسخ الاحتياطي',Database]]:user.role==='doctor'?[['profile','الملف الشخصي',UserRound],['hours','ساعات العمل والطابور',Clock3],['security','الأمان',ShieldCheck],['appearance','المظهر واللغة',Palette]]:[['profile','الملف الشخصي',UserRound],['security','الأمان',ShieldCheck],['appearance','المظهر واللغة',Palette]];
 useEffect(()=>{if(isAdmin&&tabs.some(x=>x[0]===tab)){api(`/settings/${tab}`).then(r=>setSettings(r.data||{})).catch(e=>toast(e.message,'error'));if(tab==='security')api('/settings/permissions').then(r=>setPermissions(r.data||{})).catch(()=>{});if(tab==='backup')api('/backups').then(r=>setBackups(r.data||[])).catch(()=>{});}if(tab==='hours'&&user.role==='doctor'){api(`/doctors/${user.id}/working-hours`).then(r=>setHours(r.data||[])).catch(e=>toast(e.message,'error'));}},[tab,isAdmin,user.id]);
 const updateSetting=(key,value)=>setSettings(s=>({...s,[key]:value}));const saveGroup=async()=>{setSaving(true);try{await api(`/settings/${tab}`,{method:'PUT',body:JSON.stringify(settings)});toast('تم حفظ الإعدادات.');}catch(e){toast(e.message,'error');}finally{setSaving(false);}};
 const saveProfile=async()=>{setSaving(true);try{const r=await api('/auth/profile',{method:'PATCH',body:JSON.stringify(profile)});toast(r.message||'تم حفظ الملف الشخصي.');refresh();}catch(e){toast(e.message,'error');}finally{setSaving(false);}};
 const updatePass=async(e)=>{e.preventDefault();if(password.next!==password.confirm){toast('كلمتا المرور غير متطابقتين.','error');return;}setSaving(true);try{await changePassword(password.current,password.next);toast('تم تغيير كلمة المرور. سجّل الدخول مجددًا.','info');}catch(err){toast(err.message,'error');}finally{setSaving(false);}};
 const saveHours=async()=>{setSaving(true);try{await api(`/doctors/${user.id}/working-hours`,{method:'PUT',body:JSON.stringify({hours:hours.map(x=>({weekday:Number(x.weekday),isOpen:Boolean(x.is_open),startTime:x.start_time,endTime:x.end_time})),avgVisitMinutes:Number(settings.avgVisitMinutes||15)})});toast('تم حفظ ساعات العمل.');}catch(e){toast(e.message,'error');}finally{setSaving(false);}};
 const runBackup=async()=>{setSaving(true);try{const r=await api('/backups',{method:'POST'});toast(r.message);setBackups(b=>[r.data,...b]);}catch(e){toast(e.message,'error');}finally{setSaving(false);}};
 const labels=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
 return <div className="settings-page"><PageHeading eyebrow={isAdmin?'إدارة النظام':'حسابي'} title="الإعدادات" description="إدارة تفضيلاتك وتهيئة بيئة العمل في Clinico."/><div className="settings-layout"><aside className="settings-nav">{tabs.map(([key,label,Icon])=><button className={tab===key?'active':''} key={key} onClick={()=>setTab(key)}><Icon size={17}/><span>{label}</span><ChevronLeft size={14}/></button>)}</aside><Card className="settings-panel">
 {tab==='profile'&&<><SettingsSection title="الملف الشخصي" description="تحديث بيانات حسابك الأساسية."><div className="form-grid two"><Field label="الاسم الكامل"><Input value={profile.fullName} onChange={e=>setProfile(v=>({...v,fullName:e.target.value}))}/></Field><Field label="البريد الإلكتروني"><Input type="email" value={profile.email} onChange={e=>setProfile(v=>({...v,email:e.target.value}))}/></Field><Field label="رقم الهاتف"><Input value={profile.phone} onChange={e=>setProfile(v=>({...v,phone:e.target.value}))}/></Field></div><Button onClick={saveProfile} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='general'&&<><SettingsSection title="الإعدادات العامة" description="اسم العيادة واللغة والمنطقة الزمنية الافتراضية."><div className="form-grid two"><Field label="اسم النظام"><Input value={settings.clinicName||''} onChange={e=>updateSetting('clinicName',e.target.value)}/></Field><Field label="اللغة الافتراضية"><Select value={settings.language||'ar'} onChange={e=>updateSetting('language',e.target.value)}><option value="ar">العربية</option><option value="en">English</option></Select></Field><Field label="المنطقة الزمنية"><Select value={settings.timezone||'Africa/Cairo'} onChange={e=>updateSetting('timezone',e.target.value)}><option value="Africa/Cairo">القاهرة (Africa/Cairo)</option><option value="UTC">UTC</option></Select></Field><Field label="العملة"><Select value={settings.currency||'EGP'} onChange={e=>updateSetting('currency',e.target.value)}><option value="EGP">جنيه مصري (EGP)</option></Select></Field></div><Button onClick={saveGroup} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='booking'&&<><SettingsSection title="قواعد الحجز والمواعيد" description="الحدود الزمنية وسياسة تأكيد أو إلغاء المواعيد."><Toggle checked={Boolean(settings.publicBooking)} onChange={v=>updateSetting('publicBooking',v)} label="السماح بالحجز العام للمرضى"/><Toggle checked={Boolean(settings.allowPatientCancel)} onChange={v=>updateSetting('allowPatientCancel',v)} label="السماح للمريض بإلغاء الموعد"/><Toggle checked={Boolean(settings.autoConfirm)} onChange={v=>updateSetting('autoConfirm',v)} label="تأكيد الحجز تلقائيًا"/><div className="form-grid two"><Field label="أقصى حجز مقدمًا (أيام)"><Input type="number" min="1" max="365" value={settings.maxAdvanceDays??30} onChange={e=>updateSetting('maxAdvanceDays',Number(e.target.value))}/></Field><Field label="الحد الأدنى قبل الموعد (ساعات)"><Input type="number" min="0" max="168" value={settings.minAdvanceHours??2} onChange={e=>updateSetting('minAdvanceHours',Number(e.target.value))}/></Field></div><Button onClick={saveGroup} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='billing'&&<><SettingsSection title="الفواتير والمدفوعات" description="إعدادات الفواتير والضريبة ووسائل الدفع."><div className="form-grid two"><Field label="العملة"><Select value={settings.currency||'EGP'} onChange={e=>updateSetting('currency',e.target.value)}><option value="EGP">جنيه مصري (EGP)</option></Select></Field><Field label="نسبة الضريبة (%)"><Input type="number" min="0" max="100" step="0.1" value={settings.taxPercent??0} onChange={e=>updateSetting('taxPercent',Number(e.target.value))}/></Field><Field label="تنسيق رقم الفاتورة" className="full-span"><Input value={settings.invoiceFormat||'INV-{YYYY}-{#####}'} onChange={e=>updateSetting('invoiceFormat',e.target.value)}/></Field></div><p className="field-help">طرق الدفع المسجلة: نقدي، بطاقة، محفظة إلكترونية. لا توجد بوابة دفع إلكترونية في هذه النسخة.</p><Button onClick={saveGroup} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='notifications'&&<><SettingsSection title="قنوات الإشعارات" description="الإشعارات داخل النظام مفعّلة دائمًا. إعداد مزودي البريد والرسائل خارجيًا اختياري."><Toggle checked={Boolean(settings.email)} onChange={v=>updateSetting('email',v)} label="إرسال البريد الإلكتروني"/><Toggle checked={Boolean(settings.sms)} onChange={v=>updateSetting('sms',v)} label="إرسال رسائل SMS"/><Field label="تذكير الموعد قبل (ساعة)"><Input type="number" min="1" max="168" value={settings.reminderHours??24} onChange={e=>updateSetting('reminderHours',Number(e.target.value))}/></Field><div className="form-grid two"><Field label="مزوّد الرسائل"><Select value={settings.smsProvider||'none'} onChange={e=>updateSetting('smsProvider',e.target.value)}><option value="none">غير مهيأ</option><option value="twilio">Twilio</option></Select></Field><Field label="حالة الربط"><Input value={settings.sms?'مفعّل — تحقق من إعداد الأسرار في الخادم':'غير متصل'} readOnly/></Field></div><Button onClick={saveGroup} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='security'&&isAdmin&&<><SettingsSection title="سياسة الأمان" description="إدارة سياسة كلمات المرور ومدة الخمول."><div className="form-grid two"><Field label="الحد الأدنى لطول كلمة المرور"><Input type="number" min="8" max="64" value={settings.minPasswordLength??8} onChange={e=>updateSetting('minPasswordLength',Number(e.target.value))}/></Field><Field label="مهلة الخمول (دقيقة)"><Input type="number" min="5" max="480" value={settings.idleMinutes??30} onChange={e=>updateSetting('idleMinutes',Number(e.target.value))}/></Field></div><Toggle checked={Boolean(settings.requireDigit)} onChange={v=>updateSetting('requireDigit',v)} label="اشتراط رقم واحد على الأقل"/><Toggle checked={Boolean(settings.requireUpper)} onChange={v=>updateSetting('requireUpper',v)} label="اشتراط حرف كبير"/><Toggle checked={Boolean(settings.requireSpecial)} onChange={v=>updateSetting('requireSpecial',v)} label="اشتراط رمز خاص"/><Button onClick={saveGroup} loading={saving}>حفظ سياسة الأمان</Button></SettingsSection><div className="settings-divider"/><SettingsSection title="مصفوفة الصلاحيات" description="تفعيل أو تعطيل صلاحيات الأدوار من الخادم."><PermissionMatrix permissions={permissions} setPermissions={setPermissions} onSave={async()=>{setSaving(true);try{await api('/settings/permissions',{method:'PUT',body:JSON.stringify(permissions)});toast('تم حفظ الصلاحيات.');}catch(e){toast(e.message,'error')}finally{setSaving(false)}}} saving={saving}/></SettingsSection></>}
 {tab==='backup'&&<><SettingsSection title="النسخ الاحتياطي للبيانات" description={fileStorageEnabled?"إنشاء نسخ محلية أو تنزيل نسخة للاحتفاظ بها خارج الخادم.":"النسخ المحلية متوقفة على Vercel لأن قرص الخادم مؤقت."}>{fileStorageEnabled?<><Toggle checked={Boolean(settings.daily)} onChange={v=>updateSetting('daily',v)} label="تفعيل النسخ الاحتياطي اليومي"/><div className="backup-callout"><Database size={22}/><div><b>قاعدة البيانات: متصلة</b><small>{backups[0]?`آخر نسخة: ${fmtDate(backups[0].created_at,true)}`:'لا توجد نسخة احتياطية بعد.'}</small></div><Button variant="outline" onClick={runBackup} loading={saving}>إنشاء نسخة الآن</Button></div><Button onClick={saveGroup} loading={saving}>حفظ الإعدادات</Button>{backups.length>0&&<div className="backup-list">{backups.map(b=><div key={b.id}><span><Database size={16}/><b>{b.path.split('/').pop()}</b><small>{fmtDate(b.created_at,true)} · {(Number(b.size)/1024/1024).toFixed(2)} MB</small></span><Button variant="outline" size="sm" icon={Download} onClick={()=>downloadFile(`/backups/${b.id}/download`,b.path.split('/').pop()).catch(e=>toast(e.message,'error'))}>تنزيل</Button></div>)}</div>}</>:<div className="backup-callout"><Database size={22}/><div><b>استخدم النسخ الاحتياطي الدائم في Neon</b><small>لا تحفظ النسخ على قرص Vercel المؤقت. تنزيل التقارير CSV يظل متاحًا.</small></div></div>}</SettingsSection><div className="danger-zone"><div><b>منطقة الخطر</b><small>قبل أي عملية حذف، صدّر جميع البيانات وراجع صلاحيات الحساب.</small></div><Button variant="danger" onClick={()=>setSecretOpen(true)}>تصدير البيانات قبل الحذف</Button></div><Modal open={secretOpen} onClose={()=>setSecretOpen(false)} title="تصدير بيانات العيادة" width="sm"><p>سيتم تنزيل ملفات CSV للمرضى والمواعيد والفواتير وسجل النشاط. لا يتم حذف أي سجل طبي من هذه الشاشة.</p><div className="modal-form-actions"><Button variant="ghost" onClick={()=>setSecretOpen(false)}>إلغاء</Button><Button onClick={async()=>{setSecretOpen(false);for(const type of ['patients','appointments','invoices','audit'])await downloadFile(`/reports/export?type=${type}`,`${type}.csv`).catch(()=>{});toast('بدأ تنزيل ملفات التصدير.');}}>تصدير البيانات</Button></div></Modal></>}
 {tab==='appearance'&&<><SettingsSection title="المظهر واللغة" description="اختر إعدادات الواجهة لهذا الجهاز."><div className="appearance-picks"><button className={profile.language==='ar'?'selected':''} onClick={()=>setProfile(v=>({...v,language:'ar'}))}><span>ع</span><b>العربية</b><small>RTL</small></button><button className={profile.language==='en'?'selected':''} onClick={()=>setProfile(v=>({...v,language:'en'}))}><span>EN</span><b>English</b><small>LTR</small></button><button className={profile.theme==='light'?'selected':''} onClick={()=>setProfile(v=>({...v,theme:'light'}))}><Sun size={21}/><b>فاتح</b></button><button className={profile.theme==='dark'?'selected':''} onClick={()=>setProfile(v=>({...v,theme:'dark'}))}><Moon size={21}/><b>داكن</b></button></div><Button onClick={saveProfile} loading={saving}>حفظ التغييرات</Button></SettingsSection></>}
 {tab==='hours'&&<><SettingsSection title="ساعات العمل والطابور" description="تحديد أيام العمل وساعات استقبال المرضى ومتوسط مدة الزيارة."><div className="working-hours-table"><div className="working-hours-head"><span>اليوم</span><span>مفتوح</span><span>من</span><span>إلى</span></div>{[0,1,2,3,4,5,6].map(day=>{const row=hours.find(x=>Number(x.weekday)===day)||{weekday:day,is_open:day!==5,start_time:'09:00',end_time:'17:00'};return <div className="working-hours-row" key={day}><b>{labels[day]}</b><Toggle checked={Boolean(row.is_open)} onChange={v=>setHours(current=>current.some(x=>Number(x.weekday)===day)?current.map(x=>Number(x.weekday)===day?{...x,is_open:v}:x):[...current,row])}/><Input type="time" value={row.start_time||'09:00'} disabled={!row.is_open} onChange={e=>setHours(current=>current.some(x=>Number(x.weekday)===day)?current.map(x=>Number(x.weekday)===day?{...x,start_time:e.target.value}:x):[...current,{...row,start_time:e.target.value}])}/><Input type="time" value={row.end_time||'17:00'} disabled={!row.is_open} onChange={e=>setHours(current=>current.some(x=>Number(x.weekday)===day)?current.map(x=>Number(x.weekday)===day?{...x,end_time:e.target.value}:x):[...current,{...row,end_time:e.target.value}])}/></div>})}</div><Field label="متوسط مدة الكشف (دقيقة)"><Input type="number" min="5" max="120" value={settings.avgVisitMinutes||15} onChange={e=>setSettings(v=>({...v,avgVisitMinutes:e.target.value}))}/></Field><Button onClick={saveHours} loading={saving}>حفظ ساعات العمل</Button></SettingsSection></>}
 {tab==='security'&&!isAdmin&&<PasswordSection password={password} setPassword={setPassword} onSubmit={updatePass} saving={saving}/>}
 {tab==='profile'&&!isAdmin&&<></>}
 {tab==='profile'&&user.role==='doctor'&&<div className="settings-divider"/>}
 {tab==='profile'&&user.role==='doctor'&&<PasswordSection password={password} setPassword={setPassword} onSubmit={updatePass} saving={saving}/>}
 {tab==='security'&&!isAdmin&&<SessionsList/>}
 </Card></div></div>;
}
function SettingsSection({title,description,children}){return <section className="settings-section"><div className="settings-section-head"><h2>{title}</h2><p>{description}</p></div><div className="settings-section-body">{children}</div></section>}
function PasswordSection({password,setPassword,onSubmit,saving}){return <SettingsSection title="تغيير كلمة المرور" description="استخدم كلمة مرور قوية لا تقل عن 8 أحرف."><form className="password-change-form" onSubmit={onSubmit}><Field label="كلمة المرور الحالية" required><Input type="password" value={password.current} onChange={e=>setPassword(v=>({...v,current:e.target.value}))} required/></Field><Field label="كلمة المرور الجديدة" required><Input type="password" value={password.next} onChange={e=>setPassword(v=>({...v,next:e.target.value}))} required minLength={8}/></Field><Field label="تأكيد كلمة المرور الجديدة" required><Input type="password" value={password.confirm} onChange={e=>setPassword(v=>({...v,confirm:e.target.value}))} required minLength={8}/></Field><Button type="submit" loading={saving}>تحديث كلمة المرور</Button></form></SettingsSection>}
function SessionsList(){const [rows,setRows]=useState([]);useEffect(()=>{api('/auth/sessions').then(r=>setRows(r.data||[])).catch(()=>{});},[]);return <div className="sessions-list"><h3>الجلسات النشطة</h3>{rows.map(x=><div key={x.id}><span><LockKeyhole size={15}/>{x.user_agent||'متصفح غير معروف'}</span><small>{x.ip} · {fmtDate(x.created_at,true)}</small></div>)}{!rows.length&&<small>لا توجد جلسات أخرى.</small>}</div>}
function PermissionMatrix({permissions,setPermissions,onSave,saving}){const roles=[['doctor','طبيب'],['receptionist','استقبال'],['patient','مريض']];const keys=['patients.read','patients.write','appointments.read','appointments.write','queue.manage','visits.write','prescriptions.write','labs.write','labs.collect','invoices.write','payments.write','reports.clinical','catalogs.write','messages.write'];const labels={'patients.read':'عرض المرضى','patients.write':'تعديل المرضى','appointments.read':'عرض المواعيد','appointments.write':'إدارة المواعيد','queue.manage':'إدارة الطابور','visits.write':'كتابة الزيارات','prescriptions.write':'إنشاء الروشتات','labs.write':'طلب التحاليل','labs.collect':'تسجيل العينات والنتائج','invoices.write':'إدارة الفواتير','payments.write':'تسجيل الدفعات','reports.clinical':'التقارير السريرية','catalogs.write':'تعديل الكتالوجات','messages.write':'الرسائل'};return <><div className="permission-table-wrap"><table className="permission-table"><thead><tr><th>الصلاحية</th>{roles.map(([r,l])=><th key={r}>{l}</th>)}</tr></thead><tbody>{keys.map(k=><tr key={k}><td>{labels[k]}</td>{roles.map(([r])=><td key={r}><input type="checkbox" checked={Boolean(permissions[r]?.[k])} onChange={e=>setPermissions(p=>({...p,[r]:{...p[r],[k]:e.target.checked}}))}/></td>)}</tr>)}</tbody></table></div><Button onClick={onSave} loading={saving}>حفظ مصفوفة الصلاحيات</Button></>}

export function ReportsPage(){const [overview,setOverview]=useState(null);const [trend,setTrend]=useState([]);const [diagnoses,setDiagnoses]=useState([]);const [loading,setLoading]=useState(true);const toast=useToast();useEffect(()=>{Promise.all([api('/reports/overview'),api('/reports/lab-trend'),api('/reports/diagnoses')]).then(([o,t,d])=>{setOverview(o.data);setTrend(t.data||[]);setDiagnoses(d.data||[]);}).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));},[]);const palette=['#0b7778','#28b7b0','#7bdad2','#e5b65c','#9a82c2','#75a8aa'];return <div className="reports-page"><PageHeading eyebrow="تحليلات العيادة · آخر 90 يومًا" title="التقارير" description="مؤشرات أداء قابلة للمتابعة مبنية على بيانات النظام." actions={<Button variant="outline" icon={Download} onClick={()=>downloadFile('/reports/export?type=appointments','appointments.csv').catch(e=>toast(e.message,'error'))}>تصدير تقرير</Button>}/><div className="stats-grid report-stats"><StatCard label="المرضى النشطون" value={overview?.activePatients?.toLocaleString('en-US')??'—'} icon={Users} caption="ملفات غير مؤرشفة" tone="teal"/><StatCard label="متوسط الانتظار" value="—" icon={Clock3} caption="يُحسب من أحداث الطابور" tone="aqua"/><StatCard label="مواعيد اليوم" value={overview?.appointmentsToday??'—'} icon={CalendarCheck2} caption="مواعيد قائمة" tone="gold"/><StatCard label="الرصيد المستحق" value={money(overview?.outstanding)} icon={Wallet} caption="الفواتير غير المسددة" tone="violet"/></div><div className="reports-grid"><Card><div className="card-heading"><div><h2>اتجاه طلبات التحاليل</h2><p>عدد الطلبات خلال آخر 8 أسابيع</p></div><FlaskConical size={18} className="muted-icon"/></div><div className="report-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend}><defs><linearGradient id="reportTeal" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#0f7778" stopOpacity={.26}/><stop offset="1" stopColor="#0f7778" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="4 4" stroke="var(--border)" vertical={false}/><XAxis dataKey="week" tick={{fontSize:11,fill:'var(--muted)'}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fontSize:11,fill:'var(--muted)'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{direction:'rtl',borderRadius:12,fontFamily:'inherit'}}/><Area dataKey="count" type="monotone" stroke="#0f7778" fill="url(#reportTeal)" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></Card><Card><div className="card-heading"><div><h2>التشخيصات الأكثر شيوعًا</h2><p>من الزيارات المسجلة</p></div><HeartPulse size={18} className="muted-icon"/></div>{diagnoses.length?<div className="diagnosis-chart"><ResponsiveContainer width="55%" height="100%"><PieChart><Pie data={diagnoses} dataKey="value" nameKey="name" innerRadius={48} outerRadius={80} paddingAngle={3}>{diagnoses.map((x,i)=><Cell key={i} fill={palette[i%palette.length]}/>)}</Pie><Tooltip contentStyle={{direction:'rtl',fontFamily:'inherit'}}/></PieChart></ResponsiveContainer><div className="diagnosis-legend">{diagnoses.slice(0,5).map((x,i)=><div key={x.name}><i style={{background:palette[i%palette.length]}}/><span>{x.name}</span><b>{x.value}</b></div>)}</div></div>:<EmptyState icon={Activity} title="لا توجد تشخيصات كافية" description="تظهر المؤشرات بعد تسجيل الزيارات."/>}</Card></div><div className="report-tiles"><h2>تقارير إضافية</h2><div>{[['الفواتير','قريبًا',ReceiptText],['السلامة','قريبًا',ShieldCheck],['الروشتات','قريبًا',FileText],['نتائج المختبر','قريبًا',FlaskConical],['الاستخدام','قريبًا',Activity],['البيانات الديموغرافية','قريبًا',Users]].map(([x,b,Icon])=><button key={x} disabled><Icon size={18}/><b>{x}</b><Badge>{b}</Badge></button>)}</div></div></div>}

export function SchedulePage(){const [rows,setRows]=useState([]);const [loading,setLoading]=useState(true);const [date,setDate]=useState(new Date());const [view,setView]=useState('week');const {user}=useAuth();const toast=useToast();const prefix=user.role==='receptionist'?'/reception':user.role==='doctor'?'/doctor':'/admin';const fetchRows=()=>{const from=new Date(date);from.setDate(from.getDate()-from.getDay());from.setHours(0,0,0,0);const to=new Date(from);to.setDate(to.getDate()+7);setLoading(true);api(`/appointments?from=${encodeURIComponent(from.toISOString())}&to=${encodeURIComponent(to.toISOString())}&pageSize=100`).then(r=>setRows(r.data||[])).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));};useEffect(()=>{fetchRows();},[date]);const days=Array.from({length:7},(_,i)=>{const d=new Date(date);d.setDate(d.getDate()-d.getDay()+i);return d;});return <div className="schedule-page"><PageHeading eyebrow="إدارة المواعيد" title="الجدول" description="عرض أسبوعي للمواعيد المسجلة لدى العيادة." actions={<Link className="btn btn-primary" to={`${prefix}/appointments/new`}><Plus size={16}/> حجز</Link>}/><Card className="calendar-card"><div className="calendar-toolbar"><div className="calendar-date-nav"><button onClick={()=>setDate(d=>new Date(d.getFullYear(),d.getMonth(),d.getDate()-7))}><ChevronRight size={17}/></button><b>{fmtDate(days[0])} — {fmtDate(days[6])}</b><button onClick={()=>setDate(d=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+7))}><ChevronLeft size={17}/></button><button className="today-button" onClick={()=>setDate(new Date())}>اليوم</button></div><div className="calendar-views">{['يوم','أسبوع','شهر'].map(x=><button key={x} className={view===(x==='أسبوع'?'week':x==='يوم'?'day':'month')?'active':''} onClick={()=>setView(x==='أسبوع'?'week':x==='يوم'?'day':'month')}>{x}</button>)}</div></div>{loading?<div className="skeleton-table"><i/><i/><i/><i/></div>:<div className="calendar-grid"><div className="calendar-time-heading">الوقت</div>{days.map(d=><div className="calendar-day-head" key={d.toISOString()}><b>{new Intl.DateTimeFormat('ar-EG-u-nu-latn',{weekday:'short'}).format(d)}</b><small>{new Intl.DateTimeFormat('ar-EG-u-nu-latn',{day:'numeric',month:'short'}).format(d)}</small></div>)}{Array.from({length:9},(_,i)=>{const hour=9+i;return <React.Fragment key={hour}><div className="calendar-time">{String(hour).padStart(2,'0')}:00</div>{days.map(d=>{const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const match=rows.filter(a=>new Date(a.startAt).getDate()===d.getDate()&&new Date(a.startAt).getHours()===hour);return <div key={key+hour} className="calendar-slot">{match.map(a=><div key={a.id} className={`appointment-chip type-${a.type}`} onClick={()=>toast(`${a.patientName} · ${a.doctorName}`,'info')} title={`${a.patientName} · ${a.doctorName}`}><b>{a.patientName}</b><small>{a.serviceName||typeLabel(a.type)}</small></div>)}</div>})}</React.Fragment>})}</div>}</Card><div className="calendar-legend"><span><i className="legend-first"/> كشف أول</span><span><i className="legend-follow"/> متابعة</span><span><i className="legend-consult"/> استشارة</span><span><i className="legend-lab"/> تحليل</span></div></div>}
function typeLabel(type){return {first:'كشف أول',follow_up:'متابعة',consultation:'استشارة',lab:'تحليل'}[type]||'زيارة'}

export function VisitEditor({visitId}){const toast=useToast();const navigate=useNavigate();const location=useLocation();const query=new URLSearchParams(location.search);const [form,setForm]=useState({patientId:query.get('patient')||'',type:'first',complaint:'',examination:'',diagnosis:''});const [patients,setPatients]=useState([]);const [visit,setVisit]=useState(null);const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);useEffect(()=>{api('/patients?pageSize=100').then(r=>setPatients(r.data||[])).catch(()=>{});if(visitId){setLoading(true);api(`/visits/${visitId}`).then(r=>{setVisit(r.data);setForm({patientId:r.data.patient_id,type:r.data.type,complaint:r.data.complaint,examination:r.data.examination,diagnosis:r.data.diagnosis});}).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));}},[visitId]);const save=async(sign=false)=>{setSaving(true);try{let id=visit?.id;if(!id){const r=await api('/visits',{method:'POST',body:JSON.stringify(form)});id=r.data.id;setVisit(r.data);}else await api(`/visits/${id}`,{method:'PATCH',body:JSON.stringify(form)});if(sign){await api(`/visits/${id}/sign`,{method:'POST'});toast('تم توقيع الزيارة.');navigate(-1);}else toast('تم حفظ مسودة الزيارة.');}catch(e){toast(e.message,'error');}finally{setSaving(false);}};if(loading)return <div className="skeleton-table"><i/><i/></div>;return <div className="visit-editor"><PageHeading eyebrow="الملف الطبي" title={visitId?'تفاصيل الزيارة':'كشف جديد'} description="سجّل الشكوى والفحص والتشخيص؛ لن تصبح الزيارة نهائية حتى توقيعها." actions={<Button variant="outline" onClick={()=>navigate(-1)}>عودة</Button>}/><div className="visit-layout"><Card><div className="form-grid two"><Field label="المريض" required><Select value={form.patientId} onChange={e=>setForm(v=>({...v,patientId:e.target.value}))} disabled={Boolean(visitId)} required><option value="">اختر المريض</option>{patients.map(p=><option key={p.id} value={p.id}>{p.fullName} — {p.fileNo}</option>)}</Select></Field><Field label="نوع الزيارة"><Select value={form.type} onChange={e=>setForm(v=>({...v,type:e.target.value}))}><option value="first">كشف أول</option><option value="follow_up">متابعة</option><option value="consultation">استشارة</option></Select></Field></div><Field label="الشكوى الرئيسية"><Textarea rows={3} value={form.complaint} onChange={e=>setForm(v=>({...v,complaint:e.target.value}))} placeholder="ما الأعراض أو سبب الزيارة؟"/></Field><Field label="الفحص السريري"><Textarea rows={5} value={form.examination} onChange={e=>setForm(v=>({...v,examination:e.target.value}))} placeholder="الملاحظات والقياسات والفحص"/></Field><Field label="التشخيص"><Textarea rows={3} value={form.diagnosis} onChange={e=>setForm(v=>({...v,diagnosis:e.target.value}))}/></Field><div className="visit-editor-actions"><Button variant="outline" onClick={()=>save(false)} loading={saving} icon={Save}>حفظ كمسودة</Button><Button onClick={()=>save(true)} loading={saving} icon={CheckCircle2}>حفظ وتوقيع الزيارة</Button></div></Card><Card className="visit-helper"><span className="helper-icon"><Stethoscope size={24}/></span><h3>إرشادات تسجيل الزيارة</h3><p>احتفظ بالتوثيق السريري كاملًا. يمكن ربط التحاليل والروشتات بالزيارة بعد حفظ المسودة.</p><div><span><ShieldCheck size={16}/> الوصول محصور بالفريق الطبي</span><span><HistoryIcon/> التعديلات مسجّلة في سجل النشاط</span></div></Card></div></div>}
function HistoryIcon(){return <Activity size={16}/>}

export function PrescriptionEditor(){const toast=useToast();const navigate=useNavigate();const location=useLocation();const patientFromQuery=new URLSearchParams(location.search).get('patient')||'';const [patients,setPatients]=useState([]);const [medications,setMedications]=useState([]);const [patientId,setPatientId]=useState(patientFromQuery);const [diagnosis,setDiagnosis]=useState('');const [recommendations,setRecommendations]=useState('');const [items,setItems]=useState([{medicationId:'',name:'',dose:'',frequency:'',route:'فموي',duration:'',instructions:''}]);const [saving,setSaving]=useState(false);const [saved,setSaved]=useState(null);const [allergyWarnings,setAllergyWarnings]=useState([]);useEffect(()=>{Promise.all([api('/patients?pageSize=100'),api('/medications')]).then(([p,m])=>{setPatients(p.data||[]);setMedications(m.data||[]);}).catch(e=>toast(e.message,'error'));},[]);const patient=patients.find(p=>String(p.id)===String(patientId));const updateItem=(i,key,value)=>setItems(current=>current.map((x,n)=>n===i?{...x,[key]:value}:x));const create=async()=>{if(!patientId){toast('اختر المريض أولًا.','error');return;}setSaving(true);try{const result=await api('/prescriptions',{method:'POST',body:JSON.stringify({patientId:Number(patientId),diagnosis,recommendations,items:items.filter(x=>x.name).map(x=>({...x,medicationId:x.medicationId?Number(x.medicationId):null}))})});setSaved(result.data);setAllergyWarnings(result.allergyWarnings||[]);toast(result.allergyWarnings?.length?'تحقق من تنبيه الحساسية قبل التوقيع.':'تم حفظ الروشتة كمسودة.');}catch(e){toast(e.message,'error');}finally{setSaving(false);}};const sign=async()=>{if(!saved?.id){await create();return;}setSaving(true);try{await api(`/prescriptions/${saved.id}/sign`,{method:'POST'});toast('تم توقيع الروشتة.');navigate(-1);}catch(e){toast(e.message,'error');}finally{setSaving(false);}};return <div className="prescription-editor-page"><PageHeading eyebrow="الملف الطبي" title="إنشاء روشتة جديدة" description="اكتب خطة الدواء مع معاينة قابلة للطباعة." actions={<Button variant="outline" icon={Printer} onClick={()=>window.print()}>طباعة</Button>}/><div className="prescription-editor-grid"><Card className="prescription-form-card"><Field label="المريض" required><Select value={patientId} onChange={e=>setPatientId(e.target.value)} required><option value="">اختر المريض</option>{patients.map(p=><option key={p.id} value={p.id}>{p.fullName} — {p.fileNo}</option>)}</Select></Field>{patient?.medical?.allergyFlag&&<div className="form-alert error"><AlertTriangle size={17}/> حساسية مسجلة: {patient.medical.allergies}</div>}<Field label="التشخيص"><Input value={diagnosis} onChange={e=>setDiagnosis(e.target.value)}/></Field><div className="form-section-title"><b>الأدوية</b><Button variant="outline" size="sm" icon={Plus} onClick={()=>setItems(v=>[...v,{medicationId:'',name:'',dose:'',frequency:'',route:'فموي',duration:'',instructions:''}])}>إضافة دواء</Button></div>{items.map((item,i)=><div className="prescription-item-form" key={i}><div className="prescription-item-head"><b>دواء {i+1}</b>{items.length>1&&<button className="icon-btn danger-icon" onClick={()=>setItems(v=>v.filter((_,n)=>n!==i))}><Trash2 size={15}/></button>}</div><Field label="اسم الدواء" required><Select value={item.medicationId} onChange={e=>{const m=medications.find(x=>String(x.id)===e.target.value);updateItem(i,'medicationId',e.target.value);updateItem(i,'name',m?.nameAr||'');if(m?.commonDoses?.[0])updateItem(i,'dose',m.commonDoses[0]);}}><option value="">اختر دواء من القائمة أو اكتب اسمه</option>{medications.map(m=><option value={m.id} key={m.id}>{m.nameAr} — {m.brand||m.class}</option>)}</Select></Field>{!item.medicationId&&<Field label="اسم الدواء" required><Input value={item.name} onChange={e=>updateItem(i,'name',e.target.value)} required/></Field>}<div className="form-grid two"><Field label="الجرعة"><Input value={item.dose} onChange={e=>updateItem(i,'dose',e.target.value)} placeholder="500 ملجم"/></Field><Field label="التكرار"><Input value={item.frequency} onChange={e=>updateItem(i,'frequency',e.target.value)} placeholder="كل 8 ساعات"/></Field><Field label="طريقة الاستخدام"><Input value={item.route} onChange={e=>updateItem(i,'route',e.target.value)}/></Field><Field label="المدة"><Input value={item.duration} onChange={e=>updateItem(i,'duration',e.target.value)} placeholder="5 أيام"/></Field></div><Field label="تعليمات"><Input value={item.instructions} onChange={e=>updateItem(i,'instructions',e.target.value)} placeholder="بعد الطعام"/></Field></div>)}<Field label="التوصيات الطبية"><Textarea rows={3} value={recommendations} onChange={e=>setRecommendations(e.target.value)}/></Field>{allergyWarnings.length>0&&<div className="form-alert error"><AlertTriangle size={17}/> توجد أدوية قد تتطابق مع حساسية مسجلة: {allergyWarnings.join('، ')}</div>}<div className="modal-form-actions"><Button variant="outline" onClick={create} loading={saving}>حفظ كمسودة</Button><Button onClick={saved?sign:create} loading={saving}>{saved?'توقيع الروشتة':'حفظ الروشتة'}</Button></div></Card><Card className="prescription-preview"><div className="preview-heading"><b>معاينة الطباعة</b><Button variant="ghost" size="sm" icon={Printer} onClick={()=>window.print()}>طباعة</Button></div><div className="rx-paper"><div className="rx-brand"><img src="/assets/images/clinico-logo.svg" alt="Clinico"/><span>روشتة طبية</span></div><div className="rx-rule"/><div className="rx-patient"><b>المريض: {patient?.fullName||'—'}</b><small>رقم الملف: {patient?.fileNo||'—'} · التاريخ: {fmtDate(new Date(),true)}</small></div>{diagnosis&&<div className="rx-diagnosis"><b>التشخيص</b><p>{diagnosis}</p></div>}<div className="rx-list">{items.filter(x=>x.name).map((item,i)=><div className="rx-item" key={i}><span className="rx-no">{i+1}</span><div><b>{item.name}</b><small>{[item.dose,item.frequency,item.route,item.duration].filter(Boolean).join(' · ')}</small>{item.instructions&&<p>{item.instructions}</p>}</div></div>)}{!items.some(x=>x.name)&&<div className="rx-empty">أضف دواء لعرضه في المعاينة.</div>}</div>{recommendations&&<div className="rx-recommendations"><b>التوصيات</b><p>{recommendations}</p></div>}<div className="rx-signature">توقيع الطبيب<br/>________________</div><div className="rx-footer">Clinico Systems · بيانات طبية سرية</div></div></Card></div></div>}

export function ThreadPage(){const location=useLocation();const navigate=useNavigate();const threadId=location.pathname.split('/').pop();const isThread=/\d+/.test(threadId);const [threads,setThreads]=useState([]);const [messages,setMessages]=useState([]);const [body,setBody]=useState('');const [thread,setThread]=useState(null);const [loading,setLoading]=useState(true);const [sending,setSending]=useState(false);const {user}=useAuth();const toast=useToast();const threadEndpoint='/threads';useEffect(()=>{if(isThread){Promise.all([api(`${threadEndpoint}/${threadId}/messages`),api(threadEndpoint)]).then(([m,t])=>{setMessages(m.data||[]);setThreads(t.data||[]);setThread((t.data||[]).find(x=>String(x.id)===threadId)||null);}).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));}else{api(threadEndpoint).then(r=>setThreads(r.data||[])).catch(e=>toast(e.message,'error')).finally(()=>setLoading(false));}},[threadId]);const send=async()=>{if(!body.trim())return;setSending(true);try{let id=thread?.id;if(!id){const patient=await api('/patients?pageSize=1');const create=await api('/threads',{method:'POST',body:JSON.stringify({patientId:patient.data?.[0]?.id,subject:'استفسار جديد',body})});id=create.data.id;setBody('');navigate(`${location.pathname}/${id}`);return;}const result=await api(`/threads/${id}/messages`,{method:'POST',body:JSON.stringify({body})});setMessages(m=>[...m,result.data]);setBody('');}catch(e){toast(e.message,'error');}finally{setSending(false);}};return <div className="inbox-page"><PageHeading eyebrow="التواصل" title={isThread?'المحادثة':'صندوق الوارد'} description="مراسلات آمنة مرتبطة بملفات المرضى."/>{!isThread?<div className="inbox-list">{threads.map(t=><button key={t.id} className="inbox-thread" onClick={()=>navigate(`${location.pathname}/${t.id}`)}><span className="avatar-mini">{t.patientName?.[0]}</span><span><b>{t.patientName}</b><small>{t.subject||'استفسار'} · {fmtDate(t.updated_at,true)}</small></span><Badge tone={t.status==='open'?'success':'neutral'}>{t.status==='open'?'مفتوحة':'مغلقة'}</Badge><ChevronLeft size={17}/></button>)}{!threads.length&&<Card><EmptyState icon={Inbox} title="صندوق الوارد فارغ" description="تظهر المحادثات الجديدة هنا."/></Card>}</div>:<Card className="thread-card"><div className="thread-head"><button className="icon-btn" onClick={()=>navigate(-1)}><ArrowRight size={18}/></button><span className="avatar-mini">{thread?.patientName?.[0]||'م'}</span><div><b>{thread?.patientName||'محادثة طبية'}</b><small>{thread?.subject||'رسائل آمنة'}</small></div><Badge tone="success">محادثة آمنة</Badge></div><div className="thread-messages">{loading?<div className="skeleton-table"><i/><i/></div>:messages.map(m=><div key={m.id} className={`chat-bubble ${Number(m.sender_id)===Number(user.id)?'mine':'theirs'}`}><p>{m.body}</p><small>{m.sender_name} · {fmtDate(m.created_at,true)}</small></div>)}{!messages.length&&!loading&&<EmptyState icon={MessageSquare} title="ابدأ المحادثة" description="اكتب رسالتك الأولى للفريق الطبي."/>}</div><div className="thread-composer"><Textarea rows={2} value={body} onChange={e=>setBody(e.target.value)} placeholder="اكتب رسالة..." onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}}/><Button icon={Send} onClick={send} loading={sending} disabled={!body.trim()}>إرسال</Button></div></Card>}</div>}
